const r = await api.get("/mails");
const items = [...r.items].sort((a, b) => new Date(b.received_at) - new Date(a.received_at));
return items.slice(0, 3).map(m => ({ id: m.id, from_name: m.from_name, from_email: m.from_email, received_at: m.received_at, subject: m.subject }));

